const HOME_KEY='learning-garden-home-v1';
const NOTE_COLORS={sage:'#e7eddf',lilac:'#eee7f5',peach:'#f7e5d9',butter:'#f4efcd',blue:'#e5f1fb',pink:'#fbeaf0'};
function defaultHome(){return {quotes:[{id:'begin',text:'You don’t have to be ready.\nYou just have to begin.',credit:''},{id:'small',text:'Small steps still move you forward.',credit:''},{id:'curious',text:'Stay curious. Make something.\nCome back tomorrow.',credit:''}],activeQuoteId:'begin',intention:'One lesson. One experiment. One little step forward.',notes:[{id:'n1',title:'A little reminder',text:'You’re allowed to be a beginner at something you care about.',color:'sage'},{id:'n2',title:'Collect small wins',text:'A working line of code. A clearer idea. A question you finally asked. It all counts.',color:'peach'},{id:'n3',title:'For the messy days',text:'Open the lesson. Try for ten minutes. Let that be enough to start.',color:'butter'}]}}
let homeSettings=defaultHome(),homeStorageOK=true,showAllHomeNotes=false;
try{const stored=localStorage.getItem(HOME_KEY);if(stored)homeSettings=validateHomeSettings(JSON.parse(stored))}catch{homeStorageOK=false}
function validateHomeSettings(v){if(!v||!Array.isArray(v.quotes)||!v.quotes.length||v.quotes.length>100||!Array.isArray(v.notes)||v.notes.length>200||typeof v.intention!=='string')throw Error('Invalid home settings');const quotes=v.quotes.map(q=>{if(typeof q.id!=='string'||typeof q.text!=='string'||!q.text.trim()||q.text.length>400||typeof q.credit!=='string'||q.credit.length>100)throw Error('Invalid quote');return {id:q.id,text:q.text,credit:q.credit}});const notes=v.notes.map(n=>{if(typeof n.id!=='string'||typeof n.title!=='string'||n.title.length>60||typeof n.text!=='string'||!n.text.trim()||n.text.length>240||!Object.hasOwn(NOTE_COLORS,n.color))throw Error('Invalid note');return {id:n.id,title:n.title,text:n.text,color:n.color}});if(new Set(quotes.map(q=>q.id)).size!==quotes.length||new Set(notes.map(n=>n.id)).size!==notes.length)throw Error('Duplicate home entries');return {quotes,notes,intention:v.intention.slice(0,180),activeQuoteId:quotes.some(q=>q.id===v.activeQuoteId)?v.activeQuoteId:quotes[0].id}}
function persistHome(){try{localStorage.setItem(HOME_KEY,JSON.stringify(homeSettings));homeStorageOK=true}catch{homeStorageOK=false}}
function mergeHomeSettings(incoming){if(!incoming)return;const quotes=new Map(homeSettings.quotes.map(q=>[q.id,q]));incoming.quotes.forEach(q=>quotes.set(q.id,q));const notes=new Map(homeSettings.notes.map(n=>[n.id,n]));incoming.notes.forEach(n=>notes.set(n.id,n));homeSettings={quotes:[...quotes.values()],notes:[...notes.values()],activeQuoteId:incoming.activeQuoteId,intention:incoming.intention};persistHome()}
function renderHome(){const quote=homeSettings.quotes.find(q=>q.id===homeSettings.activeQuoteId)||homeSettings.quotes[0];$('breadcrumb').textContent='Home';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view==='home'));$('content').innerHTML=`<div class="home-welcome"><div><h1>Hey Sanjana,<br>keep your curiosity <em>alive.</em></h1><p>A little learning. A little courage. A little more you.</p></div><div class="home-doodle" aria-hidden="true"><svg viewBox="0 0 120 120"><path d="M60 3 68 36 91 12 82 45 116 39 88 60 116 81 82 75 91 108 68 84 60 117 52 84 29 108 38 75 4 81 32 60 4 39 38 45 29 12 52 36Z" fill="#d0c2e4"/><circle cx="60" cy="60" r="19" fill="#f7f8f3"/><path d="M51 63Q60 73 69 63" stroke="#526346" stroke-width="2.5" fill="none"/><circle cx="53" cy="55" r="2" fill="#526346"/><circle cx="67" cy="55" r="2" fill="#526346"/></svg><span>good things<br>take practice.</span></div></div><section class="quote-stage" aria-label="Your motivational quote"><div class="quote-top"><span class="home-pill">✳ WORDS TO COME BACK TO</span><button id="editHomeQuote" aria-label="Edit your quote">✎ Edit quote</button></div><div class="quote-mark" aria-hidden="true">“</div><blockquote>${esc(quote.text)}</blockquote>${quote.credit?`<p class="quote-credit">— ${esc(quote.credit)}</p>`:'<p class="quote-credit">A reminder, just for you.</p>'}<div class="quote-bottom"><div><button class="textbtn" id="nextHomeQuote">Another reminder ↻</button><span class="quote-count">${homeSettings.quotes.findIndex(q=>q.id===quote.id)+1} / ${homeSettings.quotes.length}</span></div><button class="textbtn" id="newHomeQuote">＋ Add your own words</button></div><span class="quote-spark" aria-hidden="true">✦</span></section><div class="home-note-heading"><div><span class="eyebrow">A FEW THINGS TO REMEMBER</span><h2>Notes to myself.</h2></div><button class="textbtn" id="newHomeNote">＋ Pin a note</button></div><div class="home-note-grid">${(showAllHomeNotes?homeSettings.notes:homeSettings.notes.slice(0,3)).map(n=>`<article class="home-sticky" style="background:${NOTE_COLORS[n.color]}"><span class="sticky-pin" aria-hidden="true">✳</span><div><h3>${esc(n.title||'Note to myself')}</h3><p>${esc(n.text)}</p></div><button data-home-note="${esc(n.id)}" aria-label="Edit note: ${esc(n.title||'Note to myself')}">✎</button></article>`).join('')||'<button class="home-sticky" id="firstHomeNote">＋ Write a little encouragement for yourself.</button>'}</div>${homeSettings.notes.length>3?`<button class="textbtn" id="toggleHomeNotes">${showAllHomeNotes?'Show fewer notes':'See all '+homeSettings.notes.length+' notes'} ↗</button>`:''}<div class="home-bottom-grid"><section class="home-intention"><div class="eyebrow">TODAY CAN BE SIMPLE</div><h2>My tiny intention.</h2><p>${esc(homeSettings.intention||'Pick one small thing to try today.')}</p><button class="textbtn" id="editHomeIntention">Set my intention ↗</button></section><section class="home-goal"><div><span class="home-pill">🔥 MY NORTH STAR</span><h2>DevFest, here I come.</h2><p>5 December 2026 · ${devfestCountdown()}</p></div><div class="home-goal-actions"><button class="primary" data-nav="board">Open my sprint ↗</button><button class="textbtn" data-nav="focus">My learning path</button></div></section></div><div class="home-footer"><span>Little by little is still a lot. <span aria-hidden="true">✦</span></span><div><button class="textbtn" data-nav="study">Start a study session ↗</button><button class="textbtn" data-nav="Course">Browse courses ↗</button><button class="textbtn" id="export">Export backup ↓</button><button class="textbtn" id="import">Import backup ↑</button></div></div><p class="home-save-note">${homeStorageOK?'Your quotes and notes save in this browser. Backups include your personal homepage.':'Browser storage is unavailable. Export a backup to keep your quotes and notes.'}</p>`}
function showQuoteEditor(isNew=false){const q=isNew?{text:'',credit:''}:homeSettings.quotes.find(q=>q.id===homeSettings.activeQuoteId)||homeSettings.quotes[0];$('homeQuoteId').value=q.id||'';$('homeQuoteText').value=q.text;$('homeQuoteCredit').value=q.credit;$('quoteFormError').textContent='';$('homeQuoteDialog').showModal()}
function showNoteEditor(id){const n=homeSettings.notes.find(n=>n.id===id)||{title:'',text:'',color:'lilac'};$('homeNoteId').value=n.id||'';$('homeNoteTitle').value=n.title;$('homeNoteText').value=n.text;$('homeNoteColor').value=n.color;$('noteFormError').textContent='';$('homeNoteDialog').showModal()}
function setupHome(){document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='editHomeQuote')showQuoteEditor();if(b.id==='newHomeQuote')showQuoteEditor(true);if(b.id==='nextHomeQuote'){const i=homeSettings.quotes.findIndex(q=>q.id===homeSettings.activeQuoteId);homeSettings.activeQuoteId=homeSettings.quotes[(i+1)%homeSettings.quotes.length].id;persistHome();render()}if(b.id==='newHomeNote'||b.id==='firstHomeNote')showNoteEditor();if(b.dataset.homeNote)showNoteEditor(b.dataset.homeNote);if(b.id==='toggleHomeNotes'){showAllHomeNotes=!showAllHomeNotes;render()}if(b.dataset.closeHome)$(b.dataset.closeHome).close();if(b.id==='editHomeIntention'){$('homeIntentionText').value=homeSettings.intention;$('homeIntentionDialog').showModal()}});$('homeQuoteForm').addEventListener('submit',e=>{e.preventDefault();const text=$('homeQuoteText').value.trim();if(!text){$('quoteFormError').textContent='Write a few words you want to remember.';return}const id=$('homeQuoteId').value||newId(),q={id,text,credit:$('homeQuoteCredit').value.trim()};const i=homeSettings.quotes.findIndex(q=>q.id===id);if(i>=0)homeSettings.quotes[i]=q;else homeSettings.quotes.push(q);homeSettings.activeQuoteId=id;persistHome();$('homeQuoteDialog').close();render();toast('Your words, your space. Quote saved.')});$('homeNoteForm').addEventListener('submit',e=>{e.preventDefault();const text=$('homeNoteText').value.trim();if(!text){$('noteFormError').textContent='Add a little note first.';return}const id=$('homeNoteId').value||newId(),n={id,title:$('homeNoteTitle').value.trim(),text,color:$('homeNoteColor').value};const i=homeSettings.notes.findIndex(n=>n.id===id);if(i>=0)homeSettings.notes[i]=n;else{homeSettings.notes.unshift(n);showAllHomeNotes=false}persistHome();$('homeNoteDialog').close();render();toast('Note pinned')});$('homeIntentionForm').addEventListener('submit',e=>{e.preventDefault();homeSettings.intention=$('homeIntentionText').value.trim();persistHome();$('homeIntentionDialog').close();render();toast('A small intention, set.')})}
